//! Budget and sizing outputs generated by actual existing Python paper-risk code.

use sadr_core::{
    finance::{Amount, FeeArithmetic, Money, Price},
    risk::{PaperCashPolicy, Portfolio, paper_cash_lots},
};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Vectors {
    schema_version: u32,
    reference: String,
    reference_domain_sha256: String,
    reference_risk_sha256: String,
    synthetic: bool,
    profile_cases: Vec<ProfileCase>,
    sizing_cases: Vec<SizingCase>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ProfileCase {
    id: String,
    policy: PaperCashPolicy,
    portfolio: Portfolio,
    expected_capital: Price,
    expected_limits: Value,
    expected_cash_budget: Amount,
    expected_planned_budget: Money,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct SizingCase {
    id: String,
    price: Price,
    fees: FeeArithmetic,
    cash_budget: Amount,
    planned_budget: Money,
    maximum: i64,
    expected_lots: u64,
    expected_reservation: Money,
}

fn vectors() -> Vectors {
    let vectors: Vectors = serde_json::from_str(include_str!(
        "../../../fixtures/rust/cash_risk_vectors.json"
    ))
    .unwrap();
    assert_eq!(vectors.schema_version, 1);
    assert_eq!(vectors.reference, "python-sadr");
    assert_eq!(vectors.reference_domain_sha256.len(), 64);
    assert_eq!(vectors.reference_risk_sha256.len(), 64);
    assert!(vectors.synthetic);
    vectors
}

#[test]
fn both_paper_profile_budgets_and_limits_match_python() {
    let vectors = vectors();
    assert_eq!(vectors.profile_cases.len(), 28);
    for case in vectors.profile_cases {
        assert_eq!(case.policy.capital(), case.expected_capital, "{}", case.id);
        assert_eq!(
            serde_json::to_value(case.policy.limits()).unwrap(),
            case.expected_limits,
            "{}",
            case.id
        );
        assert_eq!(
            case.policy.cash_budget(&case.portfolio).unwrap(),
            case.expected_cash_budget,
            "{}",
            case.id
        );
        assert_eq!(
            case.policy.planned_budget(&case.portfolio).unwrap(),
            case.expected_planned_budget,
            "{}",
            case.id
        );
    }
}

#[test]
fn planned_loss_sizing_and_full_cash_reservation_match_python() {
    let vectors = vectors();
    assert_eq!(vectors.sizing_cases.len(), 160);
    for case in vectors.sizing_cases {
        let result = paper_cash_lots(
            case.price,
            &case.fees,
            case.cash_budget,
            case.planned_budget,
            case.maximum,
        )
        .unwrap();
        assert_eq!(result.lots, case.expected_lots, "{}", case.id);
        assert_eq!(result.reservation, case.expected_reservation, "{}", case.id);
    }
}
